import re
src=open('feed.html').read();rows=re.findall(r"^ \['(.*?)','(.*?)',.*?'(rt-\d\d)','([A-F])','(.*?)'",src,re.M)
o=["# Real Time · feed v3 · legendas (conta Leandro, 16/11/2026, revisadas pelo social-media)","Blog SEO: título com palavra-chave, gancho próprio, subtítulos, exemplo, conclusão, chamada e 4 hashtags (tema + nicho + local). Sem preço e sem promessa. Ordem de postar = número do post.\n"]
for i,(rot,tit,ft,Lx,ex) in enumerate(rows):
  t,g,intro,exm,conc,h=L[ft]; nome=re.sub(r"[\[\]]","",tit)+(" "+ex if Lx=='D' else "")
  o+=[f"## {i+1:02d} · {nome} ({rot})",f"**{t}**\n",g+"\n","### O que é",intro+"\n","### Na prática",exm+"\n","### Resumo",conc+"\n","✅ Reserve pelo WhatsApp (98) 99133-1727. Seu job é na Real Time.\n",h+"\n"]
open('LEGENDAS.md','w').write("\n".join(o))
u=open('../FOTOS-USADAS.md').read().split('\n');hdr=u[:4]
open('../FOTOS-USADAS.md','w').write("\n".join(hdr+[f"| {ft} | {i+1:02d} {re.sub(r'[\[\]]','',tit)} | instagram-v3 |" for i,(rot,tit,ft,Lx,ex) in enumerate(rows)]+[u[-1]]))
